# 세션 1 (H2 콘솔 1)
set autocommit false;
update member set money=500 where member_id='memberA';
# Update count: 1
# 커밋하지 않고 둔다

# 세션 2 (H2 콘솔 2)
set autocommit false;
set lock_timeout 3000;
update member set money=1000 where member_id='memberA';

# 3 초 뒤
# Timeout trying to lock table "MEMBER"; SQL statement:
# update member set money=1000 where member_id='memberA' [50200-232]

# 대기 중에 세션 3 에서 조회하면
select id, statement from information_schema.sessions;
# ID | STATEMENT
# 4  | null
# 5  | update member set money=1000 where member_id='memberA'

# 자바에서
@Test
void lockTimeout() {
    // 세션 1 이 락을 쥔 상태에서
    assertThatThrownBy(() -> service.update("memberA", 1000))
            .isInstanceOf(SQLException.class);
}

# org.h2.jdbc.JdbcSQLTimeoutException:
#   Timeout trying to lock table "MEMBER" [50200-232]

# 예외 코드 50200 - 7.5 절에서 이 숫자를 쓴다

# 세션 1 이 커밋하면
commit;
# 세션 2 는 이미 실패한 뒤라 다시 실행해야 한다
